parameters.jsCode:
// One request = one item. Output exactly one item describing whether the
// request is acceptable and, if not, which HTTP status to answer with.
const req = $input.first().json;

// --- 1. Authentication: shared secret in the x-api-key header ---
// Node lower-cases header names, so 'X-Api-Key' arrives as 'x-api-key'.
const expected = $env.WEBHOOK_API_KEY;
if (!expected) {
  return [{ json: { valid: false, status: 500, error: 'server_misconfigured',
                    message: 'WEBHOOK_API_KEY is not set on the server' } }];
}
const provided = req.headers['x-api-key'];
if (!provided || provided !== expected) {
  return [{ json: { valid: false, status: 401, error: 'unauthorized',
                    message: 'Missing or invalid x-api-key header' } }];
}

// --- 2. Input validation: codice_cliente must look like CL-00001 ---
const raw = req.body?.codice_cliente;
const code = (raw ?? '').toString().trim().toUpperCase();
if (!/^CL-\d{5}$/.test(code)) {
  return [{ json: { valid: false, status: 400, error: 'bad_request',
                    message: 'codice_cliente is required and must match CL-00000' } }];
}

// --- 3. Clean item for the next nodes ---
return [{ json: { valid: true, customer_code: code } }];

